var TAUX={EUR:1,USD:1.08,GBP:0.85,CHF:0.97,CAD:1.47};var TAUX_DATE="";var LAST_DE="EUR",LAST_VERS="USD";
function pairRate(){return TAUX[LAST_VERS]/TAUX[LAST_DE];}
function tauxNote(){var el=document.getElementById("src");var r=pairRate().toFixed(4);if(TAUX_DATE){el.textContent="Taux BCE du "+TAUX_DATE+" : 1 "+LAST_DE+" = "+r+" "+LAST_VERS+".";}else{el.textContent="Taux de secours (hors-ligne) : 1 "+LAST_DE+" ≈ "+r+" "+LAST_VERS+".";}}
try{fetch("https://api.frankfurter.dev/v1/latest?base=EUR&symbols=USD,GBP,CHF,CAD").then(function(r){return r.json();}).then(function(j){if(j&&j.rates&&j.rates.USD){TAUX.USD=j.rates.USD;TAUX.GBP=j.rates.GBP;TAUX.CHF=j.rates.CHF;TAUX.CAD=j.rates.CAD;TAUX_DATE=j.date||"";}tauxNote();}).catch(function(){tauxNote();});}catch(e){tauxNote();}
function conv(){var r=TAUX;var m=parseFloat(document.getElementById("mnt").value)||0;var d=document.getElementById("de").value;var v=document.getElementById("vers").value;LAST_DE=d;LAST_VERS=v;var eur=m/r[d];var out=eur*r[v];document.getElementById("res").innerHTML="<b>"+m+" "+d+" ≈ "+out.toFixed(2)+" "+v+"</b>";tauxNote();}
conv();

function factureData(){var m=parseFloat(document.getElementById("f4").value)||0;var t=parseFloat(document.getElementById("f5").value)||0;return {n:document.getElementById("f0").value,a:document.getElementById("f1").value,b:document.getElementById("f2").value,c:document.getElementById("f3").value,m:m,t:t,ttc:m*(1+t/100),d:new Date().toLocaleDateString("fr-FR"),h:new Date().toLocaleTimeString("fr-FR")};}
function factureCard(x){return "<div id=\"facture-print\"><div class=\"inv-card\"><div class=\"inv-top\"><span>FACTURE</span><span>N° "+x.n+" · "+x.d+"</span></div><div class=\"inv-cols\"><div><b>Émetteur</b><br>"+x.a+"</div><div><b>Client</b><br>"+x.b+"</div></div><table class=\"inv-table\"><tr><th>Description</th><th style=\"text-align:right\">Montant</th></tr><tr><td>"+x.c+"</td><td style=\"text-align:right\">"+x.m.toFixed(2)+" €</td></tr><tr><td>TVA ("+x.t+" %)</td><td style=\"text-align:right\">"+(x.ttc-x.m).toFixed(2)+" €</td></tr><tr class=\"inv-total\"><td>Total TTC</td><td style=\"text-align:right\">"+x.ttc.toFixed(2)+" €</td></tr></table><div class=\"hint\">Aperçu généré le "+x.d+" à "+x.h+"</div></div></div>";}
function fact(){var x=factureData();document.getElementById("res").innerHTML=factureCard(x);document.getElementById("res").scrollIntoView({behavior:"smooth",block:"nearest"});}
function downloadFacture(){var x=factureData();if(window.jspdf&&window.jspdf.jsPDF){var doc=new window.jspdf.jsPDF({unit:"mm",format:"a4"});doc.setFontSize(22);doc.text("FACTURE "+x.n,14,20);doc.setFontSize(12);doc.text("Date : "+x.d,14,30);doc.text("De : "+x.a,14,42);doc.text("A : "+x.b,14,50);doc.text("Objet : "+x.c,14,58);doc.text("Total HT : "+x.m.toFixed(2)+" EUR",14,72);doc.text("TVA ("+x.t+" %) : "+(x.ttc-x.m).toFixed(2)+" EUR",14,80);doc.setFontSize(16);doc.text("Total TTC : "+x.ttc.toFixed(2)+" EUR",14,92);doc.save("facture-"+x.n+".pdf");return "pdf";}var doc2="<!DOCTYPE html><html lang=\"fr\"><head><meta charset=\"utf-8\"><title>Facture "+x.n+"</title></head><body>"+factureRows(x)+"</body></html>";var blob=new Blob([doc2],{type:"text/html"});var a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="facture.html";document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(a.href);a.remove();},500);return "html";}
function factureRows(x){return "<h1>FACTURE "+x.n+"</h1><p>De : "+x.a+"<br>A : "+x.b+"<br>Objet : "+x.c+"<br>Total TTC : "+x.ttc.toFixed(2)+" EUR</p>";}
fact();
